(function (all) { var mine = all["tr"] = all["tr"] || {}; var add = {"manual.831d0f72d242":"Başlarken","manual.f2f53974b760":"Freally Capture; Windows, macOS ve Linux için bir masaüstü stüdyosudur. Bu kılavuz, güncel sürüm olan 1.2.1 sürümünü anlatır.","manual.4b5f10daa08b":"Freally Capture'ı açın. İlk açılışta sizden lisans sözleşmesini kabul etmenizi ister; ardından bir kurulum sihirbazı ekran kartınızı ve işlemcinizi denetler ve her birinin gerekçesini belirterek bir kodlayıcı, bir tuval boyutu ve bir bit hızı önerir.","manual.fe88634050bf":"Stüdyo; <strong>Sahneler</strong>, <strong>Kaynaklar</strong>, <strong>Mikser</strong> ve <strong>Denetimler</strong> panelleriyle birlikte program önizlemesinde açılır. Hesap yoktur, oturum açmanız da gerekmez.","manual.4c937d2528ca":"<strong>macOS</strong>'ta Sistem Ayarları → Gizlilik ve Güvenlik bölümünde <strong>Ekran Kaydı</strong> iznini — kullanıyorsanız <strong>Kamera</strong> ve <strong>Mikrofon</strong> izinlerini de — verin, ardından uygulamayı yeniden açın. <strong>Wayland kullanan Linux</strong>'ta hangi ekranın ya da pencerenin paylaşılacağını masaüstünün kendi iletişim kutusu sorar.","manual.adc8f305f8f8":"İlk kaynağınızı ekleyin (bkz. <a href=\"#build-a-scene\">Bir sahne oluşturun</a>); artık kayda ya da canlı yayına hazırsınız.","manual.46e49bd74b1d":"Bir sahne oluşturun","manual.f779d891c1f2":"Bir sahne, ekran kartında birleştirilen bir kaynak yığınıdır. Bir kaynak birkaç sahne tarafından paylaşılabilir.","manual.5a1c5f778fdb":"<strong>Kaynaklar</strong> panelinde <strong>Kaynak ekle</strong>'ye tıklayın ve bir tür seçin: <strong>Ekran</strong>, <strong>Pencere</strong>, <strong>Oyun</strong>, <strong>Web Kamerası / Yakalama Kartı</strong>, <strong>Tarayıcı</strong>, <strong>Medya</strong>, <strong>Görüntü</strong>, <strong>Metin</strong>, <strong>Renk</strong> ya da <strong>Ses</strong>.","manual.2a2d9e2015b5":"Bir <strong>Ekran Yakalama</strong> ekleyin: program önizlemesi ekranınızla dolar.","manual.80c8e9c8176f":"Bir <strong>Web kamerası</strong> kaynağı ekleyin, onu tuvalin bir köşesine sürükleyin ve tutamaçlarıyla yeniden boyutlandırın.","manual.264150f36676":"Üstüne bir <strong>Görüntü</strong> ya da <strong>Tarayıcı</strong> katmanı ekleyin. Listedeki sıra tuvaldeki sıradır: listenin en üstü en öndedir.","manual.a329c46899d6":"<strong>Sahneler</strong> panelinde daha fazla sahne oluşturun — örneğin “Birazdan başlıyor”, “Oyun” ve “Hemen dönüyorum” — ve aralarında geçiş yapın.","manual.9c8d5730d1bb":"<strong>İpucu:</strong> Paylaşılan bir kaynağın özelliklerini bir kez değiştirin; onu kullanan her sahnede değişir.","manual.fd869e76d280":"<strong>Önizleme:</strong> Windows'ta, macOS'ta ve X11 kullanan Linux'ta program önizlemesi doğrudan ekran kartından çizilir; bu yüzden sürükleme, ölçekleme ve döndürme anında gerçekleşir. Wayland'de aynı tuval üstü düzenleme olanaklarıyla standart bir önizleme kullanılır.","manual.87eca68fecaa":"Filtreler ve geçişler","manual.36a962cf3902":"Her kaynağa ekran kartında çalışan filtreler ekleyin ve bir sahnenin bir sonrakine nasıl yerini bırakacağını seçin.","manual.4708b4dbab34":"Kroma anahtarı ekleyin","manual.9df34cebcaf5":"Bir kaynağa — örneğin yeşil perdeli bir kameraya — sağ tıklayın ve <strong>Filtreler</strong>'i seçin.","manual.9981601a6174":"<strong>Kroma Anahtarı</strong> ekleyin ve <strong>Anahtar renk</strong>, <strong>Benzerlik</strong>, <strong>Yumuşaklık</strong> ve <strong>Taşma</strong> değerlerini ayarlayın: anahtarlanan renk tuvalde canlı olarak kaybolur.","manual.b76bd309a9f6":"Gerektikçe başka filtreler ekleyin — <strong>Renk Düzeltme</strong>, <strong>LUT</strong>, <strong>Bulanıklaştır</strong>, <strong>Maske</strong>, <strong>Keskinleştir</strong> — ve zinciri yeniden sıralamak için onları sürükleyin.","manual.db41fe5a40e4":"Bir geçiş ayarlayın","manual.bea9e11be98d":"<strong>Denetimler</strong>'de geçiş seçiciyi açın, <strong>Kesme</strong>, <strong>Solma</strong>, <strong>Kaydırma</strong>, <strong>Süpürme</strong>, <strong>Stinger</strong> ya da <strong>Luma Silme</strong> seçeneğini seçin ve bir süre belirleyin.","manual.eada58ce5b2e":"Bir <strong>Stinger</strong> için medyayı ve geçiş noktasını; bir <strong>Luma Silme</strong> için degradeyi ve yumuşaklığını seçin.","manual.79756cb8b209":"Geçişin oynadığını görmek için sahne değiştirin. Stüdyo Modu'nda geçiş, önizlemeyi programa gönderdiğinizde oynar.","manual.2c0c025b4264":"Birleştirici ve görsel efektler","manual.b768e85eff32":"3B eğme, çıkış keyer'ları, dondurma ve klonlama, bir bulanıklık ailesi, kurallı hareket geçişleri, bir gölgelendirici stüdyosu, Bézier maskeleri ve track matte stinger'lar.","manual.d2b720eca5a5":"3B eğme ve perspektif","manual.d665cc2f2296":"Bir öğede <strong>Dönüşümü düzenle</strong>'yi açın ve kaynağı 3B olarak sabitlemek için <strong>X Eğimi</strong>, <strong>Y Eğimi</strong> ve bir <strong>Perspektif</strong> gücü ayarlayın. Eğimi olmayan bir dönüşüm tam olarak eskisi gibi işlenir.","manual.c4077ba2b72d":"Çıkış keyer'ları","manual.d4220af54ed9":"<strong>Araçlar → Çıkış Keyer'ları</strong>'nı açın ve herhangi bir kaynağı, tüm sahnelerin üzerinde ve her sahne değişikliği boyunca kalan bir katman olarak <strong>Program çıkışının</strong> üzerine ekleyin — bir kanal logosu, bir CANLI rozeti, bir alt üçte bir yazısı.","manual.0677e571c1f8":"Katmanları yeniden sıralayın ve her birinin opaklığını, konumunu, boyutunu ve açık/kapalı durumunu ayarlayın. Önizlemede, kayıtta, yayında ve çoklu görünümde aynı şekilde görünürler.","manual.1e484119e149":"Kare dondurma ve kaynak klonlama","manual.4cdb8e22f58b":"Bir kaynağa sağ tıklayın, <strong>Filtreler</strong>'i açın ve <strong>Dondur</strong> ekleyin: son kareyi programda, önizlemede, kayıtta ve yayında aynı anda tutar. Dondurmayı kaldırmak için kapatın.","manual.59fd957b48dc":"Tek bir akışı birkaç sahneye ya da noktaya yerleştirmek için bir kaynağın satırındaki <strong>Klonla</strong> düğmesine (⧉) tıklayın; her klonun kendi dönüşümü ve filtreleri olur.","manual.a90410d6b30c":"Bulanıklıklar","manual.eeb69e428aa3":"Bir kaynağın <strong>Filtreler</strong> bölümünde Gauss bulanıklığının yanındaki bulanıklıklardan birini ekleyin: <strong>yönlü</strong> (bir açıyla hareket izi), <strong>dairesel</strong> (bir merkez etrafında dönme), <strong>Yakınlaştırma</strong> (dolly-zoom izi) ya da <strong>Pikselleştir</strong> (mozaik).","manual.54261c9f6b8f":"Hareket geçişi ve geçiş kuralları","manual.ef17a04962be":"<strong>Hareket</strong> geçişini seçin: her iki sahnede de bulunan öğeler kesilmek yerine eski konum, ölçek, döndürme ve kırpmalarından yenilerine kayarak geçer; yalnızca bir sahnede bulunan öğeler ise belirir ya da kaybolur.","manual.e31792f9e737":"Bir sahne çiftine kendi geçişini ve süresini vermek için <strong>Araçlar → Geçiş kuralları</strong>'nı açın. Bir öğenin kendi girişi için <strong>Dönüşümü düzenle</strong> altında bir <strong>ortaya çıkarma</strong> belirmesi ayarlayın.","manual.bb4e30a1ea68":"WGSL gölgelendirici stüdyosu","manual.e475acf03bea":"Filtre olarak bir <strong>kullanıcı WGSL efekti</strong> ekleyin ve onu canlı olarak düzenleyin. Kaydırıcıları <code>// @param</code> ek açıklamalarından oluşturulur; yerleşik bir galeride gri tonlama, ters çevirme, tarama çizgileri ve vinyet bulunur.","manual.424ca3316822":"<strong>İpucu:</strong> Bir gölgelendirici siz yazarken derlenir ve denetlenir. Geçersiz bir gölgelendirici yok sayılır ve kaynak filtresiz işlenir — asla çökme olmaz.","manual.c24e8b5ee2c0":"Bézier maskeleri","manual.37870edaacbc":"<strong>Serbest el maskesi</strong> filtresini ekleyin ve kapalı bir yol çizin: tutamaçları sürükleyin, nokta eklemek için çift tıklayın, nokta silmek için sağ tıklayın. Hazır şekiller, her kenar için ayrı yumuşatma ve ters çevirme seçeneği vardır.","manual.f44ad1306530":"Şekli bir geçiş olarak yeniden kullanmak için herhangi bir yolu gri tonlamalı bir <strong>luma silme</strong> deseni olarak dışa aktarın.","manual.e4c8b0c52b3e":"Track matte stinger'lar","manual.b35494db6ce6":"Bir stinger'ı, saydamlığını dolgu ve matte <strong>Yan yana</strong> ya da <strong>Üst üste</strong> yerleştirilmiş bir <strong>Track matte</strong> olarak taşıyacak şekilde ayarlayın; böylece saydamlık, onu atan kodeklerde (H.264 ve HEVC) de korunur. İsteğe bağlı olarak, stinger çalarken onun kendi sesinin altında <strong>program sesini kısın</strong>.","manual.3879f0c73d18":"Katmanlar ve daha fazla kaynak","manual.cea21c089e39":"Tekrar, çalma listeleri, başlıklar, ölçerler, bir istatistik katmanı, zamanlayıcılar, bir giriş katmanı ve iki ağ akışı; tamamı <strong>Kaynaklar</strong> panelindeki <strong>+ / Kaynak ekle</strong> menüsünden.","manual.4a459b922e4b":"Anında tekrar","manual.2e042aa67065":"Önce tekrar arabelleğini hazırlayın (<strong>Denetimler</strong> panelinde <strong>Tekrarı hazırla</strong>), ardından <strong>+ / Kaynak ekle</strong> menüsünden <strong>Anında Tekrar</strong>'ı seçin ve bir sahneye yerleştirin.","manual.d7645da473a6":"Tekrar kısayolunuzla son saniyeleri programa aktarın — yeniden kodlanmadan kopyalanır ve <strong>%100</strong>, <strong>%50</strong> ya da <strong>%25</strong> hızda oynatılır; uydurma kareler eklenmeden yavaşlatılır. Oynarken ileri geri sarabilir ya da duraklatabilirsiniz.","manual.5b8095e70de0":"Sonunda kaynak kendini temizler; böylece yayın kendiliğinden canlıya döner.","manual.6433eaab9b10":"<strong>İpucu:</strong> Ağır çekim tekrar bilerek sessizdir: yavaşlatılmış ses bozulurdu, bu yüzden taklit edilmek yerine dışarıda bırakılır.","manual.f0b63d46cd74":"Medya çalma listesi ve arka plan müziği","manual.37ed12f9d130":"<strong>Medya Çalma Listesi (kesintisiz)</strong> ekleyin ve her öğe için giriş ve çıkış noktaları ile işaret noktaları içeren sıralı bir liste oluşturun. Listenin tamamı tek bir kod çözücüden oynatılır; bu yüzden geçişler kare hassasiyetindedir ve gerçekten kesintisizdir.","manual.ef41fa6ad9b5":"Nasıl çalışacağını seçin — <strong>Döngü</strong>, <strong>Karıştır</strong> ya da <strong>sonuncuda kal</strong> — ve sonraki ve önceki kısayollarıyla listede ilerleyin. Yalnızca ses içeren bir çalma listesi tuvalde <strong>geçerli parçanın adını</strong> gösterir ve kendi mikser şeridinden çalar; duymak için o şeridin <strong>İzleme</strong> düğmesine tıklayın.","manual.6e641ae2bd92":"Ekranda hiçbir şey göstermeden çalan müzik için bunun yerine <strong>+ / Kaynak ekle → Arka plan müziği…</strong> seçeneğini seçin ve isterseniz karıştırılmış olarak bir ya da daha fazla <code>.mp3</code>, <code>.wav</code> veya <code>.flac</code> dosyası seçin. Bir video arka planının kendi sesini kapatır; böylece her zaman yalnızca tek bir ses duyulur.","manual.b9aad55133bf":"Başlık ve skor tablosu tasarımcısı","manual.5382c093aaef":"Tasarımcıyı açmak için <strong>Başlık / Skor Tablosu</strong> ekleyin: konturlu ve gölgeli metinler ile giriş ve çıkış animasyonlarıyla (solma, kaydırma, silme) <strong>Metin</strong>, <strong>Görüntü</strong> ve <strong>Şekil</strong> katmanlarını üst üste yerleştirin.","manual.7b8fea70655a":"Alanları izlenen bir dosyaya (bir CSV hücresi ya da bir JSON işaretçisi) veya bir stüdyo değişkenine bağlayın, ardından canlı olarak yönetin: sahneye dokunmadan bir adı değiştirin, skoru düzenleyin ya da animasyonu oynatın.","manual.88a9422e37a9":"Ses görselleştirici","manual.87f4a5bdd624":"<strong>Ses Görselleştirici</strong> ekleyin ve bir stil seçin — <strong>Spektrum çubukları</strong>, bir <strong>Osiloskop</strong> ya da stereo <strong>VU metreler</strong> — ardından onu herhangi bir mikser şeridine, kanala ya da ana mikse bağlayın. Bir arka plan videosunun sesini de gösterir.","manual.0ae90a461adb":"Yeşil, sarı ve kırmızı bantlar için kaynağın <strong>Özellikler</strong> bölümünde <strong>Klasik renkler</strong>'i açın ya da tek bir düz renk için kapalı bırakın. Boyut, çubuk sayısı ve düşüş hızı da oradadır.","manual.0d1ceffb08ba":"<strong>İpucu:</strong> Görselleştirici <strong>fader'dan sonra</strong> dinler; bu yüzden sessize alınmış bir kaynak düz görünür: tam olarak duyduğunuzu gösterir.","manual.ec642e1cf0cc":"İstatistik katmanı, split zamanlayıcısı ve giriş katmanı","manual.6b4fe6f81cb0":"İstatistik panelinin ölçtüğü değerleri tuvalde göstermek için <strong>Performans İstatistikleri (HUD)</strong> ekleyin — saniyedeki kare sayısı, CPU, bellek, GPU birleştirme süresi, kaybolan kareler ve canlı bit hızı; her satır açılıp kapatılabilir. GPU kullanımı ölçülmediği için bilerek dışarıda bırakılmıştır.","manual.cbd8a4b88736":"<strong>Speedrun Split Zamanlayıcısı</strong> ekleyin, bir LiveSplit <code>.lss</code> dosyasını içe aktarın ve kişisel rekorunuza, en iyi bölümlerinize ya da ortalamanıza karşı genel split, geri al, atla ve sıfırla kısayollarıyla çalıştırın. Dosya yalnızca okunur; bir koşu asla dosyaya geri yazılmaz.","manual.fbf4bbeaf903":"Klavyeyi, fareyi ve oyun kumandasını canlı göstermek için dört düzenden birinde (WASD, kompakt klavye, çift çubuklu kumanda, 8 yönlü dövüş çubuğu) <strong>Giriş Katmanı (tuşlar/kumanda)</strong> ekleyin. Klavye ve fare Windows'ta çalışır; oyun kumandaları üç sistemin hepsinde çalışır.","manual.bf794edb3c25":"Sosyal medya ve kanallar çubuğu","manual.5f898056ef11":"<strong>+ / Kaynak ekle</strong> menüsünden <strong>Sosyal Medya Çubuğu</strong> ekleyin: kullanıcı adlarınızı listeleyen bir panel. Her satır için bir platform seçin — renkli rozetler olarak <strong>YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord</strong> ya da kendi etiketiniz ve renginizle <strong>Özel</strong> — ve kullanıcı adını yazın (örneğin <code>@mychannel</code>). İsteğe bağlı bir başlık satırı ekleyin (“Beni takip edin”), satırları yeniden sıralayın ve metin boyutunu ve renkleri ayarlayın.","manual.1dab9389547a":"Her alan kaynağın <strong>Özellikler</strong> bölümünde düzenlenebilir kalır. Kullanıcı adı olmayan satırlar atlanır; böylece tam bir liste tutup yalnızca kullandıklarınızı doldurabilirsiniz.","manual.1a4ac3c2e0bf":"Öne çıkan sohbet mesajı","manual.c5d58a7d58be":"<strong>Araçlar → Öne çıkan sohbet mesajı…</strong>'nı (ya da komut paletini) açın. Çalışan her sohbet katmanından en yeni satırları listeler: birini, yayının ve kaydın izleyicilerinin gördüğü bir bant olarak programa sabitlemek için o satırdaki <strong>Öne çıkar</strong>'a tıklayın.","manual.162d364796a2":"İletişim kutusunda <strong>Bant</strong> ve <strong>Metin</strong> renklerini ayarlayın ve yayından kaldırmak için <strong>Temizle</strong>'ye tıklayın. Sabitleme, tasarım gereği yeniden başlatmada temizlenir: dünün selamı bugünün yayınına sızmaz.","manual.89a84c53e014":"İmleç vurgusu ve tıklama efektleri","manual.d0a5d9fb047d":"Bir Ekran ya da Pencere yakalamasına sağ tıklayın, <strong>Filtreler</strong>'i açın ve <strong>İmleç efektleri</strong> ekleyin: bir <strong>İmleç halesi</strong> (renk ve yarıçap), renk kodlu sol ve sağ <strong>Tıklama halkaları</strong> ve imlecin yanında isteğe bağlı <strong>Tuş gösterimi</strong>. Değişiklikler canlı görünür.","manual.4a17c44757e4":"<strong>Not:</strong> İmleç efektleri yalnızca Windows'ta çalışır; macOS ve Linux imleci kendileri çizer. Giriş katmanı ve tuş gösterimi girdiyi <strong>yalnızca açıkken</strong> okur ve doğrudan görüntüye çizer: hiçbir şey saklanmaz ya da günlüğe kaydedilmez.","manual.8bdb1aadf964":"Ağ kaynakları: LAN alımı ve Freally Link","manual.797fe86a1fe8":"Bu bilgisayarda bir dinleyici açmak için <strong>LAN Alımı (SRT/RTMP dinleyici)</strong> ekleyin, ardından bir telefon kamera uygulamasını, bir kodlayıcıyı ya da ikinci bir bilgisayarı gösterilen adrese yönlendirin (bir QR koduyla birlikte gösterilir). Akış, kendi mikser şeridiyle sahneye gelir. SRT isteğe bağlı bir AES parolası taşıyabilir; RTMP'nin kendine ait bir kimlik doğrulaması yoktur, bu yüzden form SRT'yi tercih eder.","manual.e2761818ccef":"Freally Capture'ın iki kopyası arasında paylaşım için <strong>gönderen</strong> bilgisayarda <strong>Freally Link</strong> çıkışını açın ve <strong>Eşleştirme anahtarını</strong> ayarlayın — anahtar olmadan açılamaz. <strong>Alan</strong> bilgisayarda <strong>Freally Link (başka bir kopya)</strong> ekleyin, <strong>LAN'ı tara</strong>'ya tıklayın ve anahtarı yazın: gönderenin programı bir kaynak olarak görünür. İki tarafın da ffmpeg'e ihtiyacı yoktur ve anahtarı olmayan bir alıcı tek bir kare bile görmez.","manual.a793cb271e32":"<strong>Not:</strong> İki ağ kaynağı da <strong>siz ekleyene kadar kapalıdır</strong>, kendi ağınızda kalır ve internete asla dokunmaz: hiçbir şey sizi bulmaz ve hiçbir şey dışarıya bağlantı kurmaz.","manual.de10be5dcf2c":"“Birazdan başlıyor” geri sayımı","manual.71b47ef78ea4":"Tek tıkla bir yayın öncesi bekleme ekranı: bir görüntü, GIF, video, degrade ya da müzik üzerinde yayın saatine kadar büyük bir geri sayım; sıfırda yanıp söner ve yayına geçmeniz için sizi bekler.","manual.303493002776":"Geri sayımı ekleyin","manual.f78f2994b5d5":"<strong>Kaynaklar</strong> panelinde <strong>+ / Kaynak ekle</strong>'yi açın ve <strong>Birazdan başlıyor…</strong> seçeneğini seçin. Sahneye tuvalin tamamını kaplayan bir geri sayım — büyük bir sayının üzerinde bir başlık yazısı — yerleştirir.","manual.c4bff5a4f06e":"<strong>Başlık yazısını</strong> girin (“Birazdan başlıyor”, “Hemen dönüyorum”), ardından zamanı <strong>saat seçici</strong> ile ayarlayın: bir <strong>saat</strong> (1–12), beşer dakikalık adımlarla bir <strong>dakika</strong> ve <strong>AM</strong> ya da <strong>PM</strong> (ÖÖ / ÖS). Kaynak, günün o saatine kadar geri sayar.","manual.59b00df516f1":"Sıfırda geri sayım <strong>yanıp söner ve 0:00:00'da kalır</strong> — asla kendi kendine sahne değiştirmez. Hazır olduğunuzda canlı sahnenize geçin. Her alan kaynağın <strong>Özellikler</strong> bölümünde düzenlenebilir kalır.","manual.1dfb2d817d39":"Bir arka plan seçin","manual.edc2450aeecd":"Dolguyu seçin: iki renkli bir <strong>Degrade</strong> (varsayılan), <strong>Düz</strong> bir renk, bir <strong>Görüntü</strong> (<strong>Gözat…</strong>'a tıklayın) ya da alttaki bir kaynağın görünmesine izin vermek için <strong>Saydam</strong>.","manual.07a5fd9ac032":"Bir <strong>GIF</strong> ya da <strong>video</strong> dosyası seçin; sayıların arkasında <strong>sığacak şekilde ölçeklenip ortalanarak</strong> döngüde oynar; böylece görüntünün tamamı görünür ve hiçbir şey kırpılmaz.","manual.1cda5be75376":"İletişim kutusundaki <strong>Gözat…</strong> ile <strong>Arka plan müziği</strong> ekleyin (MP3, WAV, FLAC, M4A, AAC, OGG ya da Opus). Döngüde çalar, önizlemede duyarsınız ve kaydın ve yayının bir parçasıdır. Bir video arka planının kendi sesi kapatılır; böylece her zaman yalnızca tek bir ses duyulur.","manual.b39b6b7add20":"<strong>İpucu:</strong> Sade bir ekranın arkasında müzik için arka planı Degrade ya da Saydam olarak bırakın ve müziği ekleyin: müzikli, temiz bir geri sayım.","manual.84f506f4fca5":"Ses mikseri","manual.480e299c8728":"Her ses kaynağını miksleyin, 6'ya kadar kanala gönderin ve mikrofonunuzu temizleyin — tamamı canlı olarak.","manual.bcbc220b3e63":"Her ses kaynağı <strong>Mikser</strong>'de bir şerittir: adı, bir seviye ölçeri, bir fader, sessize alma, izleme, filtreler ve kanal noktaları (1–6).","manual.03b920dc5376":"Seviyeyi ayarlamak için bir fader'ı sürükleyin, <strong>Sessize al</strong> ya da <strong>İzleme</strong> düğmesine tıklayın ve kaynağı 6 kanaldan herhangi birine gönderin.","manual.9a9991c7dc36":"Bir kaynağın <strong>filtreler</strong> bölümünü açın ve <strong>Gürültü Azaltma</strong> (klasik sinyal işleme, yapay zekâ yok), <strong>Gürültü Kapısı</strong>, <strong>Kompresör</strong>, <strong>Limitleyici</strong>, <strong>EQ</strong> ya da <strong>Kazanç</strong> ekleyin.","manual.1a58b91bc5aa":"Bir <strong>Bas-konuş</strong> ya da <strong>Bas-sustur</strong> kısayolu atayın ve programın ses yüksekliği için <strong>LUFS</strong> ölçerini izleyin.","manual.7158a36ed4d5":"<strong>macOS notu:</strong> macOS, uygulamalara “duyduğunuz sesi” kendiliğinden vermez. Kullanılabildiği yerde ScreenCaptureKit sesini (macOS 13 ya da üstü) kullanın ya da BlackHole gibi sanal bir aygıt kurup onu sistem sesi kaynağınız olarak seçin. Freally Capture size yol gösterir ve bir kaynak açılamasa bile kayda devam eder.","manual.bfdd510698ef":"Kayıt","manual.e39b756fce99":"Programı ekran kartınızın donanım kodlayıcısıyla birkaç kanala ya da Capture'ın kendi biçiminde kayıpsız olarak kaydedin.","manual.ad438c2dbf4b":"<strong>Ayarlar → Çıkış</strong> bölümünde bir kodlayıcı seçin. Freally Capture <strong>NVENC</strong>, <strong>Quick Sync</strong>, <strong>AMF</strong>, <strong>VAAPI</strong> ya da <strong>VideoToolbox</strong> kodlayıcılarını bulur ve en iyisini seçer; işlemcide çalışan <strong>x264</strong> her zaman yedek olarak hazırdır.","manual.3bc1870f8449":"Bir kap seçin — <strong>MP4</strong>, <strong>MKV</strong>, <strong>MOV</strong> ya da <strong>WebM</strong> — veya başka hiçbir şeyin kurulmasını gerektirmeyen, Capture'ın kendi kayıpsız <strong>freally-video</strong> biçimini (<code>.frec</code>) seçin.","manual.e2a332927058":"Mikrofon, sistem sesi ve konuklarınız kurgu için ayrı kalsın diye kaynakları ses kanallarına (6'ya kadar) gönderin. İsteğe bağlı olarak <strong>dosya bölmeyi</strong> ve <strong>yayın sırasında ayrı kanallı yerel kopyayı</strong> açın.","manual.e0fa2f5a9430":"<strong>Denetimler</strong>'de <strong>Kaydı başlat</strong>'a tıklayın. Yeşil bir <strong>REC</strong> noktası süreyi ve kanal sayısını gösterir. Dosyayı tamamlamak için <strong>Durdur</strong>'a tıklayın.","manual.b1eb969490f1":"<strong>Kodek notu:</strong> H.264 ve AAC (ayrıca HEVC ya da AV1) içeren MP4, patentlerle korunan kodekler kullanır; bunları <em>pakete dahil olmayan</em> <strong>ffmpeg</strong> sağlar: Freally Capture onu ilk ihtiyaç duyduğunuzda indirir ve doğrular. Kayıpsız <strong>freally-video</strong> biçimi hiçbir şey indirmeyi gerektirmez.","manual.691bff5377a8":"Kayıt ve tekrarda derinlik","manual.3c2d08430816":"Dosyanın etrafındaki her şey: her kaynağın ayrı kayıtları, bir klip kırpıcı, gerçek saydamlık, olaylarda bölme ve işaretçiler, kayıt sonrası görevler, bir bütünlük denetimi ve SMPTE zaman kodu. Bunların hepsi siz açana kadar kapalıdır ve hiçbiri internete çıkmaz.","manual.537ffa2b9063":"Kaynak başına ISO kaydı","manual.e57aa725fa41":"<strong>Ayarlar → Çıkış</strong>'ı açın ve <strong>ISO kaydı</strong> bölümünü bulun. Temiz kaydını istediğiniz her kaynak için <strong>“{name}” kaynağını ayrı bir ISO dosyası olarak kaydet</strong> seçeneğini açın: her biri birleştirmeden önce, tuval boyutunda ve kare hızında kaydedilir; böylece her dosya bir kurgu zaman çizelgesinde programla hizalanır. Her uzaktan konuk bir kaynaktır; bu yüzden her konuk da bir dosya alır.","manual.4bce8f25ec9c":"İşlenmiş görünüm için <strong>Kaynağın filtreleriyle kaydet</strong> seçeneğini işaretli bırakın ya da ham kaynak için işaretini kaldırın; ardından her kaydın <strong>ISO biçimi</strong> ve <strong>ISO video kodlayıcı</strong> ayarlarını seçin. Ses filtrelerden sonra ama fader'dan ve sessize almadan önce alınır; böylece bir miksaj kararı bir ISO dosyasını asla sessiz bırakmaz.","manual.7f29ae4e2c55":"<strong>İpucu:</strong> Orta sınıf bir ekran kartı iki ISO kaydını rahatça kaldırır; her ek kayıt bir işleme ve kodlama daha gerektirir ve panel bunu belirtir.","manual.b2aad668b8b9":"Tekrar ve klip kırpıcı","manual.c8af16e1cd4f":"Kayıtlar listesinden kaydedilmiş bir kaydı <strong>Kırp</strong> penceresinde açın, <strong>Bir kare geri</strong> ve <strong>Bir kare ileri</strong> ile kare kare ilerleyin ve izlerken noktalarınızı <strong>Giriş noktası</strong> ve <strong>Çıkış noktası</strong> ile belirleyin.","manual.1f80dfd03a36":"Dışa aktarmadan önce rozete bakın. Yeşil bir <em>“Yeniden kodlamadan dışa aktarılır”</em> rozeti, giriş noktasının bir anahtar karede olduğu anlamına gelir (neredeyse anında ve kayıpsız); kehribar rengi rozet yeniden kodlama yapılacağı konusunda uyarır — kayıpsız bir kesim için giriş noktasını yaslamak üzere <strong>Anahtar kare</strong>'ye basın. <strong>Klibi dışa aktar</strong>'a ya da dikey bir sürüm dışa aktarmak için <strong>9:16</strong>'ya tıklayın.","manual.8a92b0b480f4":"Saydamlıkla kayıt","manual.79bfd450e6aa":"Programı saydam bir arka plan üzerinde Capture'ın <code>.frec</code> biçimine kaydetmek için <strong>Ayarlar → Çıkış</strong> bölümünde <strong>Saydamlıkla kaydet (alfa)</strong> seçeneğini açın. Kayıt kendi saydam işlemesini alır; böylece önizlemeniz ve yayınınız normal görüntüyü korur. Kayıtlar listesinden, kurgu programınız için bir <strong>ProRes 4444</strong> ya da <strong>QuickTime Animation (QTRLE)</strong> <code>.mov</code> dosyası dışa aktarın; MP4 ve MKV saydamlığı düzleştirir.","manual.fade0a9d0454":"<strong>Not:</strong> Saydamlık <code>.frec</code> başlığında yalnızca bir bayraktır; bu yüzden bu dosyalar <code>.frec</code>'in oynatıldığı her yerde oynatılır ve eski dosyalar opak olarak açılır.","manual.33e5c9a96c5d":"Bölme ve otomatik işaretçiler","manual.5596d47693a3":"<code>.frec</code> bölme ayarlarında bir <strong>sahne geçişi</strong>, bir <strong>işaretçi</strong> ya da bir <strong>akış adımı</strong> gerçekleştiğinde yeni bir dosya başlatmayı seçin. Her parça o olayın tam karesinde başlar ve bir parça en az bir saniye sürer; böylece art arda gelen olaylar bir yığın küçük dosya oluşturamaz.","manual.7fc20a49c196":"Sahne geçişlerini, kaydedilen tekrarları, yeniden bağlanmaları, kare kaybı patlamalarını, alarmları ve kural eylemlerini bölüm olarak işaretlemek için <strong>Stüdyo olaylarında bölüm işaretçilerini otomatik ekle</strong> seçeneğini açın. Bunlar, kısayolunuzla eklediğiniz işaretçilerin yanında MKV bölüm başlıklarına ve kaydın yanındaki <code>.chapters.txt</code> dosyasına yazılır.","manual.519fceb746f3":"Kayıttan sonra: hat ve bütünlük denetimi","manual.561bb55d7a18":"Her profil için sabit bir adım setinden bir <strong>Kayıt sonrası hattı</strong> oluşturun — <strong>Doğrula</strong>, <strong>MP4'e yeniden paketle</strong>, <strong>Ses düzeyini normalleştir</strong>, <strong>Yeniden adlandır</strong>, <strong>Klasöre taşı</strong>, <strong>Klasöre kopyala</strong>, <strong>Dosya yöneticisinde göster</strong> ve <strong>Lua betiklerine bildir</strong>. Hat, canlı bir kuyrukla arka planda çalışır ve ilk hatada durur. Bilerek “herhangi bir komutu çalıştır” adımı yoktur.","manual.2f93cddd1f21":"Bütünlük denetimini bir kayıttan sonra ya da istediğiniz zaman çalıştırın; <strong>Kap</strong>, <strong>Video sürekliliği</strong>, <strong>Ses sürekliliği</strong>, <strong>ses ve video iç içe geçmesi</strong> ve <strong>Süre</strong> için sade bir Tamam, uyarı ya da başarısız sonucu alırsınız. <code>.frec</code> dosyaları derinlemesine denetlenir; diğer dosyalar ffmpeg üzerinden bir yapı ve kod çözme denetiminden geçer.","manual.0d291aee5546":"Durdurduğunuzda paylaşılabilir bir kopya dışa aktarın","manual.124d2a00ed27":"<strong>Ayarlar → Çıkış</strong> bölümünde, kap <code>.frec</code> olarak ayarlıyken <strong>Ana kaydın yanına paylaşılabilir bir MP4 da kaydet</strong> seçeneğini işaretleyin. Bir kayıt bittiğinde, arka planda çalışan bir dışa aktarma, kayıpsız ana kaydın yanına herkesin oynatabileceği bir <code>.mp4</code> yazar.","manual.a37303723389":"Kopya kayıt sonrası kuyruğunda görünür, hiçbir şeyin üzerine yazmayacak şekilde adlandırılır ve ana kayda asla dokunmaz. Siz açana kadar kapalıdır.","manual.7ed8656eb1ff":"SMPTE LTC zaman kodu","manual.3d97874c3064":"<strong>SMPTE Zaman Kodu (LTC)</strong>'yu açın, <strong>Bir kanala LTC üret</strong> seçeneğini açın ve harici kaydedicileri ve kameraları beslemek için mikser kanalını ve kare hızını seçin. İstatistik katmanında bir zaman kodu satırı göstermek ve LTC bölüm işaretçileri eklemek için <strong>LTC okunacak kaynak</strong> ayarını bir ses girişine getirin. Klasik ses zaman kodu; tamamen çevrimdışı, 24, 25 ve 30 fps'de tek kare hassasiyetinde.","manual.a9f690169703":"Canlı yayına çıkın","manual.8f6df4580812":"Bilgisayarınızdan bir platforma RTMP ya da RTMPS üzerinden doğrudan yayın yapın — asla bizim bir sunucumuz üzerinden değil.","manual.dba22b61cdcc":"<strong>Ayarlar → Yayın</strong>'ı açın ve <strong>Hedef ekle</strong>'ye tıklayın. <strong>Twitch</strong>, <strong>YouTube</strong>, <strong>Kick</strong>, <strong>Facebook</strong>, <strong>Trovo</strong> ya da <strong>Özel RTMP</strong> seçeneğini seçin.","manual.2192731aac47":"<strong>Yayın anahtarınızı</strong> yapıştırın — bilgisayarınızda saklanır ve maskelenmiş olarak gösterilir — ve o hizmet için bit hızını ve kodlayıcıyı ayarlayın.","manual.040014e94f16":"<strong>Denetimler</strong>'de <strong>Yayına başla</strong>'ya tıklayın. <strong>Canlı</strong> ışığı yanar ve istatistik paneli bit hızınızı, kaybolan kareleri ve yayının sağlık durumunu gösterir.","manual.0cd441959cb4":"Bağlantınız koparsa Freally Capture <strong>kendiliğinden yeniden bağlanır</strong> ve yerel kaydınız, yayın ne olursa olsun devam eder. İsterseniz bir <strong>yayın gecikmesi</strong> ayarlayın.","manual.dc8ebcea4893":"Durdurmak için <strong>Yayını bitir</strong>'e tıklayın.","manual.973adc03e43c":"Yayın güvenliği","manual.53fa9293a65e":"Yayını kaybetmemek — öncesinde, sırasında ve sonrasında.","manual.de8792b14216":"Öncesinde: canlıya çıkış öncesi kontrol listesi","manual.ed9a4b7bfaf5":"<strong>Yayına başla</strong>'ya tıklamak önce bir kontrol listesi çalıştırır: yayın hedeflerinin anahtarları girilmiş mi, kullanılabilir bir kodlayıcı bulundu mu, her kaynak sağlıklı mı ve kayıt için yeterli disk alanı var mı — her biri yeşil ya da kırmızı, tek tıklık düzeltmeyle — ayrıca mikrofon ve masaüstü sesi seviyeleri ile tekrar arabelleği hakkında, yalnızca ekran içeren bir yayını asla engellemeyen hatırlatmalar. Bir ayar, <strong>engelleyici her denetim yeşil olana kadar Yayına başla'yı bekletebilir</strong>; aksi halde “Yine de yayına başla” seçeneği vardır.","manual.9b63c5c64ba1":"Sırasında: alarmlar, sağlık durumu ve yedek kodlayıcıya geçiş","manual.9c386b745073":"<strong>Güvenlik alarmları</strong>, canlı yayındayken ya da kayıt yaparken izler: sessiz program sesi, sürekli kırpılma, siyah ya da donmuş görüntü ve düşük disk <em>tahmini</em> (“mevcut bit hızıyla yaklaşık 22 dakika kaldı”). Kapatabileceğiniz bir başlık olarak görünürler ve ekran okuyucular bunları duyurur — asla yayını kesen bir iletişim kutusu değil.","manual.b7c8c66a5330":"<strong>Kaynak durumu paneli</strong> (komut paleti → “Kaynak durumu…”) her kaynağın durumunu, kare hızını, son karesinin yaşını, kaybolan karelerini ve yeniden başlatmalarını listeler; her biri için <strong>Yeniden başlat</strong> ve <strong>Özellikler</strong> ile.","manual.92bd60ef963b":"Donanım kodlayıcısı bir yayının ya da kaydın ortasında arızalanırsa — bir sürücü sıfırlaması, yük altındaki bir ekran kartı — <strong>kodlayıcı yedeklemesi</strong> başka bir donanım kodlayıcısına ya da x264'e geçer. Yayın yeniden bağlanır ve açık kalır, kayıt yeni bir dosyada devam eder ve bir mesaj tam olarak ne olduğunu söyler. Ağ sorunları asla bir geçişe yol açmaz.","manual.50a02fe4fe7b":"<strong>Panik düğmesi</strong> (seçtiğiniz genel bir kısayol), programı — ve dikey tuvali ve tüm projektörleri — bir gizlilik ekranına keser, her yakalamayı durdurur ve mikrofon dahil tüm sesi kapatır; bu sırada yayın ve kayıt bağlı kalır. Geri dönmek bilinçli, iki adımlı bir onay gerektirir. Gizlilik ekranının rengini ya da görüntüsünü <strong>Ayarlar → Kısayollar</strong> bölümünde kısayolun yanında ayarlayın.","manual.a73a2857361e":"Sonrasında: güvenli kayıtlar ve düzenli çıkış","manual.bf07b060e7e7":"MP4 ve MOV kayıtları <strong>parçalı</strong> olarak yazılır; böylece bir çökme ya da elektrik kesintisi yine de oynatılabilir bir dosya bırakır (MKV ve <code>.frec</code> zaten böyleydi). Bir oturum kaydın ortasında sona ererse, bir sonraki açılış tek tıkla bir <code>(repaired)</code> kopyasına <strong>Onar</strong> seçeneği sunar; orijinaline asla dokunulmaz.","manual.da5eeb31c1b8":"Canlı yayındayken, kayıt yaparken ya da tekrar hazırken çıkmak, ne olacağını gösterir, ardından <strong>sırayla</strong> kapanır: yayını sonlandırır, kaydı tamamlar, tekrar arabelleğini kaydeder, çalışmanızı kaydeder.","manual.26b3f2c32e05":"<strong>Kayıt dosya adları</strong>, kayıtlar, tekrarlar ve hareketsiz görüntüler için belirteçlerden — <code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code> — oluşturulan bir şablonu (<strong>Ayarlar → Çıkış</strong>) izler; tekrarlar ve hareketsiz görüntüler için ayrı klasörler kullanılır.","manual.27c3f23547ac":"<strong>Tanılamayı dışa aktar</strong>, teknik ayrıntılardan oluşan bir paketi bilgisayarınızdaki bir dosyaya kaydeder; paket, yayın anahtarları, parolalar, dosya yolları ve adlar asla içinde bulunmasın diye katı bir izin listesiyle oluşturulur. İçeriğini önce okuyabilirsiniz; kaydettiğiniz yerde kalır ve hiçbir yere gönderilmez.","manual.5199babf9b90":"Kaynaklar ve aygıtlar","manual.306121fdda68":"Cam ile tuval arasındaki her şey: test sinyalleri, senkron kalibrasyonu, dosyadan metin, zamanlayıcılar, kısayol haritası, mikserde derinlik ve gerçek aygıt denetimleri.","manual.5eacf1ee941f":"Test sinyalleri ve ses/görüntü senkron kalibrasyonu","manual.920b7abd63cc":"Bir <strong>Test sinyali</strong> kaynağı ekleyin (<strong>Kaynaklar → + → Test sinyali</strong>): renk çubukları, bir kalibrasyon ızgarası, bir hareket taraması, −20 dBFS'de 1 kHz'lik bir referans tonu ya da ses/görüntü senkronu için birleşik bir <strong>flaş ve bip</strong> — görüntü ve ses tek bir saatten üretilir. Kamera takılı olmadan bir projektörü, bir kodlayıcıyı ya da bir yayın hedefini denetleyin.","manual.788073298328":"<strong>Ses/görüntü senkron kalibrasyonu</strong> tezgâhını açın (komut paleti → “Ses/görüntü senkron kalibrasyonu…”). Hizalanacak kamerayı ve mikrofonu seçin, kamerayı yanıp sönen programa doğrultun (iletişim kutusu bunun için tam ekran bir projektör açabilir) ve yaklaşık on iki saniye ölçüm yapmasını bekleyin. Birkaç döngü boyunca flaşı ve bipi bulur ve ölçülen kaymayı mikrofona uygulamayı önerir; elle kaydırıcı yedek olarak kalır. Ölçüm ekranınız ve hoparlörleriniz üzerinden yapılır; bu yüzden onların kendi küçük gecikmeleri de ölçümün bir parçasıdır — ve bir başarısızlık <em>nedenini</em> söyler.","manual.825c83c405fb":"Zamanlayıcılar, saatler ve dosyadan metin","manual.85622b429b51":"Bir <strong>Zamanlayıcı</strong> kaynağı bir saat (kendi biçiminizle ve isteğe bağlı sabit bir UTC farkıyla), bir <strong>Geri sayım</strong> (bir süre boyunca ya da günün bir sonraki saatine kadar — sıfırda yanıp sönebilir ya da sahne değiştirebilir), bir <strong>Kronometre</strong> ya da <strong>canlıya çıkışınızdan veya kayda başlamanızdan bu yana geçen süreyi</strong> gösterir. Onu <strong>Özellikler</strong> bölümünden başlatın, duraklatın ve sıfırlayın ya da <em>tüm</em> zamanlayıcıları birden yöneten iki genel kısayolu atayın (<strong>Ayarlar → Kısayollar</strong>).","manual.fcd4f802968f":"Bir <strong>Metin</strong> kaynağı <strong>izlenen bir dosyadan okuyabilir</strong> (<strong>Özellikler → Dosyadan oku</strong>): bir <code>.txt</code> dosyasının tamamı, bir CSV hücresi (sütun adına ya da numarasına göre) ya da bir JSON değeri (<code>/teams/0/score</code> gibi bir işaretçi). Değişiklikler yarım saniye içinde görünür. Arkasında hiçbir hizmet olmayan skor tabloları ve alt üçte bir yazıları.","manual.1d106549f0ce":"Kısayol haritası ve mikser konsolu","manual.5d6ad89f147c":"<strong>Kısayol Haritası</strong> (komut paleti → “Kısayol haritası…”) <em>her</em> atamayı — genel eylemleri ve her kaynağın bas-konuş ve bas-sustur kısayollarını — aranabilir ve filtrelenebilir biçimde listeler ve çakışmaları dürüstçe işaretler: iki farklı biçimde yazılmış aynı kısayol paylaşılan olarak gösterilir ve sistemin reddettiği (başka bir uygulamaya ait olduğu için) bir tuş bunu belirtir. <strong>Kopya kâğıdını dışa aktar</strong>, İndirilenler klasörünüze Markdown bir başvuru dosyası yazar.","manual.e32e382b9753":"Her mikser şeridinde <strong>Pan</strong> (stereo denge; ortadayken tam olarak pan olmamasıyla aynıdır ve çift tıklama onu sıfırlar), <strong>PFL solo</strong> (izleme yalnızca solo yapılmış şeritleri duyar; program miksi asla değişmez) ve <strong>mono</strong> indirgeme bulunur. Pan ve mono, şeridin “⋯” menüsündedir; solo şeridin kendisindedir.","manual.5dbd70dfc92d":"Aygıt derinliği: taramasızlaştırma (deinterlacing) ve kamera denetimleri","manual.f8e60899a881":"Bir video yakalama aygıtının <strong>Özellikler</strong> bölümü, eski kameralar ve konsollarla beslenen yakalama kartları gibi geçmeli akışlar için <strong>Deinterlacing</strong> (taramasızlaştırma) sunar: alan sırasıyla birlikte atma, bob, doğrusal, karıştırma ya da harekete uyarlanır. Her sistemde aynı şekilde çalışır; değiştirmek aygıtı yeniden başlatır.","manual.34192e6d30fd":"<strong>Kamera denetimleri</strong> — pozlama, beyaz dengesi, odak, yakınlaştırma, kazanç ve daha fazlası — kamera çalışırken aynı <strong>Özellikler</strong> bölümünde görünür. Windows ve Linux standart UVC denetimlerini kullanır; macOS sistemin bildirdiği her şeyi gösterir, ki bu çoğu zaman hiçbir şeydir ve panel, hiçbir işe yaramayan kaydırıcılar göstermek yerine bunu söyler. Her ayar, kamera yeniden takıldığında ya da uygulama yeniden başladığında tekrar uygulanan <strong>o kameraya ait bir profile</strong> kaydedilir; <strong>Profili sıfırla</strong> varsayılanlara döndürür.","manual.f77f10d8c967":"Otomasyon ve denetim","manual.726216fb4de1":"Stüdyonun kurallar, makrolar ve donanım denetleyicileriyle kendi kendini yönetmesini sağlayın — her biri tek ve sabit bir stüdyo komutları listesiyle sınırlıdır; böylece hiçbir otomasyon bir dosyayı adlandıramaz, bir program başlatamaz ya da internete ulaşamaz.","manual.193521bd4921":"Kurallar, makrolar ve değişkenler","manual.e8ee7ccab125":"<strong>Araçlar → Otomasyon kuralları ve makrolar…</strong>'ı açın ve bir kural ekleyin. Dokuz tetikleyiciden birini seçin (bir sahne geçişi, yayının başlaması ya da durması, kaydın başlaması ya da durması, bir kaynak hatası, ses seviyesinin bir eşiği aşması, sistemin boşta kalması, bir pencerenin odak alması, günün bir saati ya da izlenen bir dosyanın değişmesi), koşullar ekleyin (bir değişkenin değeri, canlı yayında olma, kayıtta olma) ve bir stüdyo eylemi seçin. Her kural <strong>devre dışı</strong> başlar: etkinleştirmek için açın.","manual.5deaa7ba718f":"Bir makroyu adlandırılmış bir adım listesi olarak oluşturun — bir eylem çalıştır, bekle, bir değişken ayarla — bir tekrar sayısı ve isteğe bağlı genel bir kısayolla. Onu uygulamadan, bir kısayoldan, bir kuraldan ya da uzaktan denetim API'sinden çalıştırın.","manual.30ee5b1326f2":"Bir makroda bir stüdyo <strong>değişkeni</strong> ayarlayın ve onu herhangi bir Metin kaynağında <code>{{name}}</code> olarak kullanın: makro değeri ayarladığı anda metin değişir.","manual.5eb10fc04538":"Denetleyiciler: MIDI, OSC ve dokunmatik panel","manual.ba0c838f1688":"<strong>Araçlar → MIDI denetimi…</strong>'ni açın ve ona bir eylem, makro, sahne geçişi, mikser fader'ı ya da sessize alma için bir ped, düğme ya da fader öğretin — stüdyonun gerçek durumunu izleyen ışıklar ve motorlu fader'larla. Siz bir MIDI bağlantı noktası seçene kadar hiçbiri açılmaz.","manual.cc993cb0d974":"TouchOSC tarzı denetleyicilerin ve ışık masalarının <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code> ve <code>/mixer/vol</code> gibi adresler göndermesine izin vermek için <strong>OSC dinle</strong> seçeneğini açın. Varsayılan olarak kapalıdır ve siz ağınıza izin vermedikçe yalnızca bu bilgisayarda dinler. OSC'nin kendine ait bir parolası yoktur.","manual.134e5f4269f9":"Herhangi bir telefona bir QR koduyla bir denetim sayfası — canlı tally'li sahne düğmeleri, mikser fader'ları ve eylem tuşları — sunmak için <strong>Araçlar → LAN paneli ve tally…</strong>'yi açın. Her istek parola gerektirir ve siz ağınıza izin vermedikçe yalnızca bu bilgisayarda dinler. Tally sayfası tam ekran kırmızı ya da yeşil gösterir; tek bir sahneyi izlemek için <code>?scene=NAME</code> ekleyin.","manual.fc4cd96b860d":"Kısayol akorları ve katmanları","manual.ec4a9a334753":"Bir kısayol alanında düz bir kısayol (Ctrl+Shift+M) ya da iki adımlı bir akor (Ctrl+K, ardından 3) atayın — ikinci tuş yalnızca akor beklemedeyken sahiplenilir. Bir atamaya bir <strong>Katman</strong> verin; böylece yalnızca o katman etkinken çalışır; katmanlar siz değiştirene kadar seçili kalır.","manual.70ad05980925":"Kameralar ve yayın akışı","manual.24b33b058b99":"<strong>Araçlar → PTZ kameralar…</strong>'ı açın, bir kamerayı VISCA-over-IP adresiyle ekleyin, adlandırılmış pan, tilt ve zoom ön ayarlarını kaydedin ve bir ön ayarı bir sahneye bağlayın; böylece o sahneye geçmek ilgili çekimi geri çağırır. PTZ ağınızda kalır ve bir kamera yalnızca adresini siz yazdığınız için vardır: hiçbir şey aranmaz.","manual.c9d86b995c5a":"<strong>Araçlar → Yayın akışını göster…</strong>'i açın ve adımları listeleyin — bir sahne, ne kadar süre kalacağı ve isteğe bağlı eylemler — elle ya da otomatik ilerleyerek, canlı bir “sıradaki” göstergesi ve kalan süreyle. Bir yayın akışı sahneleri olağan, geri alınabilir yolla değiştirir ve sahne koleksiyonunuzu asla düzenlemez.","manual.5c94bed2d737":"<strong>Not:</strong> Her kural, makro, MIDI ya da OSC ataması, panel düğmesi ve yayın akışı adımı, uzaktan denetim API'siyle aynı sabit komut listesinden geçer; böylece hiçbir denetleyici, uygulamanın kendi düğmelerinin yapamadığı bir şeyi yapamaz. Her ağ dinleyicisi varsayılan olarak kapalıdır ve siz ağınıza izin vermedikçe bu bilgisayarda kalır; OSC ve panel ayarları, bağlantı noktası açılmadan önce ağ trafiğinin şifrelenmediği konusunda sizi uyarır.","manual.1f3fd1c7ddc9":"Çoklu yayın","manual.dcac0a03a29b":"Aynı anda birkaç platforma yayın yapın — doğrudan bilgisayarınızdan, arada hiçbir aktarma hizmeti olmadan.","manual.42d9628818da":"<strong>Ayarlar → Yayın</strong> bölümünde iki ya da daha fazla yayın hedefi ekleyin ve her birini açın.","manual.4144fe0d9694":"Farklı bir bit hızına ihtiyaç duyan bir platforma kendi kodlayıcı ayarlarını verin.","manual.cb21d6bb96be":"<strong>Yayına başla</strong>'ya tıklayın: açık olan tüm hedeflere aynı anda yayın yaparsınız. İstatistik paneli her hedefin sağlık durumunu ve bit hızını gösterir; bir hedefin başarısız olması diğerlerini asla düşürmez.","manual.aba9a5f55973":"İsterseniz aynı anda ayrı kanallı bir yerel kopya kaydedin ve yayın yaparken tekrar kısayoluyla tekrarları kaydedin.","manual.af9343c245a7":"<strong>Bugün ücretsiz:</strong> her özellik — çoklu yayın, SRT ve WHIP, her filtre, betik yazımı, tekrar, geçiş paketleri ve uzaktan denetim API'si — bugün herkes için ücretsizdir. Gelecekteki sürümler satılabilir.","manual.c08320c45003":"Yayın güvenilirliği ve içgörü","manual.532ab322d03c":"Yayınınızı prova edin, ölçün ve açıklayın. Buradaki her şey varsayılan olarak kapalı ya da etkisizdir ve hiçbiri internete çıkmaz.","manual.80390ae1a9d7":"Ağ simülatörü","manual.7e620ced841e":"<strong>Ayarlar → Yayın</strong> bölümünde <strong>Ağ simülatörü (provalar)</strong>'nü açın ve bir <strong>Profil</strong> seçin — <strong>Otel Wi-Fi</strong>, <strong>Mobil erişim noktası</strong> ya da kendi <strong>Bant genişliği</strong>, <strong>Gecikme</strong>, <strong>Jitter</strong> ve zamanlanmış <strong>Kesinti</strong> sürelerinizle <strong>Özel</strong>. Yalnızca bir provanın yerel çıkışını etkiler; böylece yeniden bağlanmaları, çoklu yayını ve bit hızı seçimlerini deneyebilirsiniz; gerçek bir yayını asla yavaşlatamaz.","manual.b22d8c51e0bd":"Prova modu","manual.083772633b86":"Tüm hattı — birleştirici, kodlayıcı, paketleyici ve gerçek yeniden bağlanma mantığı — <strong>bilgisayardan hiçbir şey çıkmadan</strong> yerel bir yedek hedefe çalıştırmak için mor <strong>Prova</strong> düğmesine basın. Bir <strong>PROVA</strong> rozeti her canlı denetimi işaretler ve yayın anahtarlarınız okunmaz bile; böylece anahtarlarınız olmadan önce de prova yapabilirsiniz. Provayı kaydedebilirsiniz de.","manual.184d64047c4c":"<strong>İpucu:</strong> Zayıf, dengesiz bir bağlantı üzerinden yeniden bağlanmayı büyük günden çok önce denemek için bir provayı ağ simülatörüyle birleştirin.","manual.d2381a584d24":"Kare kaybı zaman çizelgesi","manual.a6a72c5410a8":"<strong>Oturum zaman çizelgesi</strong>, oturumun tamamını — işleme süresi, kodlayıcı kuyruğu, her hedefin bit hızı ve kaybolan kareleri, yeniden bağlanmalar, sahne geçişleri, işaretçiler ve alarmlar — yakınlaştırılabilir tek bir grafikte kaydeder. İstatistik paneli <em>şu anı</em> gösterirken zaman çizelgesi sonradan “43. dakikada ne oldu?” sorusunu yanıtlar.","manual.6e9fee1e85fa":"Oturum raporu ve kodlayıcı karşılaştırma testi","manual.9dd812cbf648":"Oturum bittiğinde yerel bir özet için <strong>Ayarlar → Yayın</strong> bölümünde <strong>Kaydın yanına bir oturum raporu (HTML + Markdown) yaz</strong> seçeneğini açın: çalışma süresi, hedef başına ortalama ve en yüksek bit hızı, kesintide geçen süre, yeniden bağlanmalar, işaretçiler, alarmlar ve kaydın konumu. Rapor bilgisayarınızda kalır ve varsayılan olarak kapalıdır.","manual.a9e574b7bd8d":"Bilgisayarınızdaki her kodlayıcı, ön ayar ve çözünürlükle kısa kodlamaları ölçmek için <strong>Kodlayıcı benchmark'ını çalıştır…</strong> seçeneğini kullanın — yaklaşık bir dakika, tamamen çevrimdışı — ardından sonuçtan <strong>Kayıt ayarlarına uygula</strong>'yı seçin. Başarısızlıklar gizlenmez, listelenir; canlı yayındayken ya da kayıt yaparken karşılaştırma testi çalışmayı reddeder.","manual.fae310275ed2":"Yalnızca yayında ya da yalnızca kayıtta görünen kaynaklar","manual.191da176dd0d":"Tek bir tuvalden, uyarıları ve sohbeti canlı yayında tutarken kaydı temiz bırakmak için bir kaynağın satırında <strong>Yayında göster</strong> / <strong>Yayında gizle</strong> ve <strong>Kayıtta göster</strong> / <strong>Kayıtta gizle</strong> seçeneklerini kullanın. Ana göz düğmesi hâlâ her şeyi denetler; önizleme, projektörler ve çoklu görünüm her zaman programın tamamını gösterir.","manual.46bad2cb618f":"Sanal kamera","manual.69ebe5277092":"Programınızı herhangi bir görüntülü görüşme uygulamasında web kamerası olarak kullanın. <strong>1.2.1 sürümünde yalnızca Windows.</strong>","manual.ba2b6aa952f7":"<strong>Denetimler</strong>'de <strong>Sanal kamerayı başlat</strong>'a tıklayın. Freally Capture, <strong>“Freally Capture Virtual Camera”</strong> adlı bir sistem kamerası ekler.","manual.cb3cb4585f19":"Zoom, Meet, Discord ya da Teams'te video ayarlarından o kamerayı seçin: programınız web kamerası olur.","manual.83db59f4a370":"Kaldırmak için <strong>Sanal kamerayı durdur</strong>'a tıklayın.","manual.91c51d55639b":"<strong>Sisteme göre:</strong> <strong>Windows</strong>'ta kamera, yönetici hakları gerekmeden kullanıcınız için kaydedilir ve durdurduğunuzda kaldırılır. Kamera <strong>henüz kod imzalı değildir</strong>; bu yüzden Windows onun hakkında uyarı verebilir ve sıkılaştırılmış bir görüntülü görüşme uygulaması onu reddedebilir; canlı bir görüşme içinde tam bir test henüz yapılmadı. <strong>macOS</strong> ve <strong>Linux</strong> kameraları, <em>bu sürümde yer almayan</em> ayrı bileşenlerdir. Freally Capture hiçbir sistemde sormadan sistem bileşeni kurmaz.","manual.98839b8e6880":"Tarayıcı kaynağı","manual.3ba821584b20":"Canlı bir web sayfasını — bir uyarı katmanını, bir skor tablosunu, bir sohbet bileşenini — doğrudan bir sahneye yerleştirin.","manual.895f07f428cd":"<strong>Kaynaklar</strong>'da <strong>+</strong>'ya tıklayın ve <strong>Tarayıcı</strong>'yı seçin.","manual.868ee19e975e":"Bir <strong>http://</strong> ya da <strong>https://</strong> adresi yapıştırın ve işleneceği boyutu ve kare hızını ayarlayın.","manual.292e94b0a782":"İlk seferde Freally Capture, <strong>Tarayıcı Çalışma Ortamı</strong> bileşenini kurmayı önerir. Bileşen siz istediğinizde indirilir ve karmasına göre doğrulanır — asla uygulamayla birlikte paketlenmez — ve <strong>Araçlar → Bileşenler</strong> bölümünden yeniden kaldırabilirsiniz.","manual.cd6d7fbd46ee":"<strong>Yalnızca http ve https yüklenir.</strong> Kural yalnızca yazdığınız adresi değil, her sayfa değişikliğini kapsar: bir sayfa <code>file://</code>, <code>javascript:</code> ya da <code>data:</code> adresine — bir yönlendirme, bir betik, bir açılır pencere ya da bir çerçeve yoluyla — geçmeye çalışırsa geçiş <strong>iptal edilir</strong>; böylece bir sayfa dosyalarınızı okuyamaz. Windows'ta sayfa Chromium'un korumalı alanında çalışır. Çalışma ortamı <strong>henüz kod imzalı değildir</strong>. Sayfanın sesi henüz yakalanmıyor: bu sürüm yalnızca görüntü içerir.","manual.9c0c8f127dd9":"Oyun yakalama","manual.2c08692420b8":"Sıradan pencere yakalamanın göremediği, özel tam ekran modundaki bir oyunu yakalayın. <strong>Yalnızca Windows.</strong>","manual.9d162e3861e9":"<strong>Kaynaklar</strong>'da <strong>+</strong>'ya tıklayın ve <strong>Oyun Yakalama</strong>'yı seçin. <strong>Önce uyarıyı okuyun</strong>: riski sade bir dille açıklar.","manual.4264b41a7732":"Riski <em>yalnızca o oyun için</em> kabul edin, ardından listeden çalışan oyunu seçin.","manual.ab3e826e90f1":"Freally Capture o oyuna küçük bir kanca yükler ve karelerini oyunun kendi kare hızında alır.","manual.082fd06e18f9":"<strong>Kullanmadan önce bunu okuyun.</strong> Oyun yakalama, <strong>oyuna bir DLL yükleyerek</strong> çalışır. Hile önleme ve antivirüs yazılımları bunu kurcalama olarak değerlendirebilir ve bu, bir hesabın <strong>yasaklanmasına</strong> yol açabilir. Hiçbir şey asla otomatik olarak yüklenmez: onayı <strong>her seferinde tek bir oyun için</strong> verirsiniz ve bu onay asla başka bir oyun için kullanılamaz — paylaşılan bir sahne koleksiyonunun içinde de asla taşınmaz. Bir oyun kancayı reddederse, Freally Capture başarısız olmak yerine bir mesajla sıradan <strong>Pencere Yakalama</strong>'ya geri döner. HDR oyunlar ve Direct3D 12 oyunları da Pencere Yakalama'yı kullanır. macOS ve Linux'ta bu kaynak sunulmaz.","manual.43fae75af922":"Tekrar arabelleği","manual.40bc664c1c0b":"Son anları bellekte tutun; böylece bir kısayol az önce olanı kaydeder.","manual.7a69241c10c2":"<strong>Denetimler</strong>'de <strong>Tekrar arabelleğini başlat</strong>'a tıklayın. Freally Capture son saniyeleri sabit boyutlu bir arabellekte tutar.","manual.684aecea2ba0":"<strong>Ayarlar</strong>'da genel bir <strong>Tekrarı kaydet</strong> kısayolu atayın.","manual.66c44777e965":"Son saniyeleri bir dosyaya kaydetmek için ona basın — yayınınızı ya da ana kaydınızı kesintiye uğratmadan. “Tekrar kaydedildi” mesajı bunu onaylar.","manual.4b598d5daf11":"Teleprompter (metin okuma ekranı)","manual.b7fc474ded62":"Kameradaki kişi için akıcı biçimde kayan bir metin — uygulamadaki bir panelde, aynalanabilen tam ekran bir projektörde ve LAN dokunmatik panelinde, hepsi aynı anda.","manual.f1c548f77750":"Teleprompter'ı <strong>Araçlar</strong> menüsünden açın, metninizi yazın ya da yapıştırın ve hızı ve yazı tipini ayarlayın. Temposunu <strong>saniyedeki karakter</strong> olarak belirleyin ya da şarkı sözlerini müzikle uyumlu okumak için <strong>BPM</strong>'e (dakikada 50–250 vuruş) geçin; iki değişiklik de çalışan bir kaydırmanın temposunu yeniden ayarlar.","manual.3a86eb91938d":"<strong>Duraklama işaretleri:</strong> kısa bir duraklama için <code> -- </code>, N saniyelik bir bekleme için <code> --N </code> yazın; tek bir işarete dönüşür — imleç onun üzerinden atlar, tek bir Delete ya da Backspace onu siler ve kopyala-yapıştır onu bütün olarak korur.","manual.dc7539148aed":"<strong>Geri sayımı başlat:</strong> okuyucunun metin hareket etmeden önce bir anlık hazırlık süresi olsun diye, hem operatörün önizlemesinde hem de projektörde gösterilen isteğe bağlı bir 3-2-1 girişini etkinleştirin.","manual.f5113c573ac4":"Okuyucu için <strong>projektörü açın</strong> (ayna modu, ışın bölücü cam için görüntüyü çevirir). Projektörü açmak operatör penceresini kapatır; böylece okuyucu okurken siz yayını ana pencereden yönetebilirsiniz; bir geri sayım etkinse projektör başa döner, geri sayar ve oynatır. Ekrandaki denetimlerden, bir kısayoldan, MIDI'den, OSC'den ya da LAN panelinden oynatın, duraklatın, durdurun, geri sarın, ileri sarın ve yeniden başlatın — her denetim senkron kalır.","manual.5298a60b0152":"<strong>Sesli okuma</strong>, metni sisteminizin kendi konuşma motoruyla önizler: Windows'un yerleşik sesleri, macOS'unkiler ve Linux'ta kuruluysa <code>spd-say</code> ya da <code>espeak-ng</code>. Pakete hiçbir konuşma motoru dahil değildir.","manual.5de1b5efa245":"<strong>Otomatik tamamlama</strong>, siz yazarken sözcükleri ve ifadeleri açık gri renkte önerir; kabul etmek için Tab'a basın. 18 dilin her birinin bilgisayarınızda kendi sözlüğü vardır ve yalnızca yazdığınız dil için yüklenir.","manual.7fb5d22a1670":"Uzaktan denetim","manual.b2ba73efdcec":"Stüdyoyu bir Stream Deck'ten ya da Companion tarzı bir denetleyiciden yönetin — varsayılan olarak kapalı, parola korumalı, kendi bilgisayarınızda.","manual.6396674fcd28":"<strong>Ayarlar → Uzaktan Denetim</strong>'i açın, <strong>WebSocket API</strong>'sini açın (varsayılan olarak kapalıdır) ve bir <strong>Parola</strong> belirleyin.","manual.56e0d6d295bb":"Siz ağınıza açıkça izin vermedikçe <code>127.0.0.1</code> adresinde — yalnızca bu bilgisayarda — dinler.","manual.344e52e3eba1":"Bir Companion ya da Stream Deck istemcisini gösterilen adrese yönlendirin. Donanım düğmeleriyle sahneleri değiştirin, geçişleri çalıştırın, sesi kapatıp açın, kaydı başlatıp durdurun ve tekrarları kaydedin.","manual.6664edd9ad4c":"Uzaktan konuklar ve yayın prodüksiyonu","manual.75ce17238f9b":"Bir uzaktan konuk oturumunu prodüksiyonu yapılmış bir yayına dönüştürün: sekize kadar konuk, canlı program üzerine çizim, bir bekleme odası, özel işaretler, her konuğun bağlantısına tek bakışta erişim ve otomatik bir ızgara. Buradaki her şey varsayılan olarak kapalı ya da atanmamıştır ve siz birini davet edene kadar hiçbir şey bağlanmaz.","manual.02d9e34002c8":"Çok konuklu oturumlar","manual.5a6c2ec7640d":"Bir uzaktan konuk oturumu başlatın ve davet bağlantısını ya da QR kodunu paylaşın: <strong>siz artı sekize kadar konuk</strong>, birden dokuza kadar bir galeri. Her konuk; kendi sessize alma denetimleri, bağlantı kalitesi, işaret kanalı ve tek tıkla yayına alma seçeneğiyle bir döşemedir.","manual.34a323a45540":"Konuk bağlantıyı bir web tarayıcısında açar — kurulacak hiçbir şey yoktur — ve kamerasını ve mikrofonunu göndermek için <strong>Katıl</strong>'a dokunur. Freally Capture'a sahip bir konuk aynı daveti bunun yerine uygulamada açabilir. Bir davetin süresi, seçtiğiniz sürenin sonunda dolar.","manual.4e31042e4a6f":"<strong>Not:</strong> Görüntü ve ses, sizinle her konuk arasında doğrudan, eşler arası ve aktarım sırasında şifrelenmiş olarak iletilir; herkese açık bir sinyalleşme hizmetinden yalnızca bağlantı el sıkışması geçer. Oturumlar dört konukla test edilmiştir; daha fazlası bant genişliğinize ve işlemcinize bağlıdır.","manual.33ff43cd0616":"Telestrator: canlı program üzerine çizim","manual.d29f651d6eb9":"<strong>Telestrator</strong>'ı açın ve bir araç seçin — <strong>Kalem</strong>, <strong>Fosforlu kalem</strong>, <strong>Ok</strong> ya da <strong>Elips</strong> — ardından doğrudan programın üzerine çizin. İşaretleriniz çizdiğiniz anda görüntünün bir parçası olur; bu yüzden yalnızca önizlemenizde değil, kayıtta ve yayında da görünürler.","manual.9aa7fc0273fb":"İşaretleri bir süre sonra <strong>Soldur</strong> ile kaybolmaya bırakın ya da siz temizleyene kadar <strong>Koru</strong>mak için <strong>Beyaz tahta modu</strong>'na geçin. Çizim tabletin basıncını izler ve <strong>İşaretleri temizle</strong> bir kısayola atanabilir (varsayılan olarak atanmamıştır).","manual.fc81cd8d37ae":"Bekleme odası","manual.c87beb96ec64":"<strong>Bekleme odası</strong>'nı açın; yeni konuklar siz <strong>Bekleme odası önizlemesi</strong>'nde kameralarını ve mikrofonlarını denetlerken yayın dışında bekler. Hazır olduklarında <strong>Yayına al</strong>'a tıklayın. Konuk, uygulamada ya da web sayfasında “bekleme odasındasınız” başlığını görür.","manual.1d47c8224f50":"İşaret ve konuşma","manual.569d461035c1":"Bir konuğa, oturumun mevcut eşler arası kanalı üzerinden — <strong>30 saniye</strong>, <strong>Toparla</strong>, <strong>Sıradaki sensin</strong> ve <strong>Daha yüksek konuş</strong> gibi ön ayarlarla — özel bir <strong>İşaret</strong> gönderin. Konuk bunu canlı bir geri sayımla görür; programda asla görünmez.","manual.c66c9d5359bf":"Bağlantı kalitesi paneli","manual.4541cc1ee0f5":"Her konuğun bağlantısını canlı izleyin — gidiş-dönüş süresi, paket kaybı, aldığınız çözünürlük ve kare hızı ve jitter — yeşil, kehribar ya da kırmızı bir rozet ve küçük bir geçmiş grafiğiyle; böylece zayıflayan bir bağlantı izleyicileriniz fark etmeden önce görünür.","manual.bf8e764221e5":"Otomatik konuk ızgaraları","manual.ffe3c227cdfc":"Yayına alınmış konukları, konuklar katıldıkça, ayrıldıkça ya da yayına alındıkça kendini yeniden düzenleyen, birden dokuza kadar düzenli bir ızgarada tutmak için <strong>Otomatik ızgara</strong>'yı açın ya da hemen düzenlemek için düzenleme düğmesine basın. Her koltuk, konuğunun adını bir <code>{{guestN}}</code> değişkeni olarak yayımlar; böylece bir başlık kaynağı kendiliğinden güncellenen bir isim levhasına dönüşür.","manual.e8630fabd4e5":"Stüdyo yönetimi ve iş akışı","manual.c8c487196725":"Bütün bir düzeni taşınabilir ve paylaşılabilir yapın, sahnelerinizin adlandırılmış sürümlerini saklayın, uygulamaya tema uygulayın ve en sevdiğiniz eylemleri bir dokunuş uzaklığına getirin — tamamı bilgisayarınızda, sunucu olmadan.","manual.f87995a7cf6c":"Sahne paketleri ve sürümler","manual.074bb2bf9453":"Çalışma alanı iletişim kutusunu <strong>Sahne Koleksiyonu → Sahne koleksiyonlarını yönet…</strong> üzerinden açın: paket, karşılaştırma, anlık görüntü, yedekleme ve panel düzeni araçlarının hepsi oradadır.","manual.8dce3a052a05":"Geçerli koleksiyonu ve dosyalarını (görüntüler, medya, LUT'lar, maskeler, yazı tipleri) taşınabilir tek bir <code>.fcappack</code> dosyasında toplamak için <strong>Paketi dışa aktar…</strong>'a tıklayın. Web adresleri ve ağ yolları pakete eklenmek yerine <em>harici</em> olarak listelenir ve yazı tipleri lisansları için işaretlenir.","manual.c1bba88df9c5":"<strong>Paket içe aktar…</strong>'a tıklayın ve bir <code>.fcappack</code> seçin: yeni bir koleksiyon olarak gelir, dosyalarını bu bilgisayarda bulur ve ona geçer.","manual.69e7b9f6e8ab":"Geçerli koleksiyonu başka bir koleksiyonla, bir paketle ya da bir anlık görüntüyle karşılaştırmak için <strong>Karşılaştır ve birleştir…</strong>'e tıklayın. Eklenen, kaldırılan ve değişen sahneleri, kaynakları, dönüşümleri, filtreleri ve görünürlüğü inceleyin, ardından tam olarak hangi değişiklikleri alacağınızı seçin. Bir sahne seçmek, kullandığı kaynakları da getirir.","manual.862a75c84629":"<strong>Anlık görüntüler…</strong>'e tıklayın, bir kontrol noktasına ad verin ve <strong>Anlık görüntü kaydet</strong>'i seçin. <strong>Geri yükle</strong> onu daha sonra geri getirir — mevcut düzeniniz önce bir anlık görüntü olarak kaydedilir; böylece bir geri yükleme asla tek yönlü olmaz. Disk kullanımları gösterilerek en fazla 50 anlık görüntü saklanır.","manual.8058b1480d14":"<strong>İpucu:</strong> Anlık görüntüler, otomatik kaydetme ve geri almanın yanında adlandırılmış bir geçmiştir. Riskli bir değişiklikten önce bir tane alın; dönebileceğiniz etiketli bir noktanız her zaman olur.","manual.1d55a62a5fdf":"Yedekleme, geri yükleme ve taşınabilir mod","manual.250b89a976de":"Çalışma alanı iletişim kutusunda <strong>Yedekle ve geri yükle…</strong>'ye, ardından her şeyi — ayarları, profilleri ve sahne koleksiyonlarını — tek bir <code>.fcapbackup</code> dosyasına kaydetmek için <strong>Yedeği dışa aktar…</strong>'a tıklayın.","manual.560e7e269f11":"Yeni bir bilgisayarda <strong>Yedekten geri yükle…</strong>'ye tıklayın, neyi alacağınızı işaretleyin (<strong>Ayarlar</strong>, <strong>Sahne koleksiyonları</strong>, <strong>Profiller</strong>) ve <strong>Seçileni geri yükle</strong>'yi seçin. Geri yüklenen koleksiyonları ve profilleri yüklemek için ardından Freally Capture'ı yeniden başlatın.","manual.5b26da4b8793":"Bir USB bellekten çalıştırmak için programın yanına <code>freally-portable.txt</code> adlı bir dosya koyun: bundan sonra tüm verileri kullanıcı profiliniz yerine programın klasöründe tutulur. <strong>Ayarlar → Hakkında</strong>, taşınabilir modun açık olup olmadığını ve verilerin nerede olduğunu gösterir.","manual.a31a49d41d7d":"<strong>Not:</strong> Yayın anahtarları ve parolalar asla bir yedeğe yazılmaz — geri yüklemeden sonra bunları yeniden girin.","manual.5b446c4ea972":"Temalar, düzenler ve hızlı eylemler","manual.8eea476bde73":"<strong>Ayarlar → Görünüm</strong>'ü açın ve paleti canlı <strong>kontrast uyarılarıyla</strong> düzenlemek için <strong>Özel</strong> temayı seçin; ardından paylaşmak için <strong>.fctheme dışa aktar…</strong> ya da <strong>.fctheme içe aktar…</strong> seçeneğini kullanın.","manual.7cc0bc3a4e74":"Çalışma alanı iletişim kutusunun <strong>Panel düzenleri</strong> bölümünde mevcut yerleşimi bir adla kaydedin ve ona geçmek için kaydedilmiş bir düzene tıklayın.","manual.c9044c09b979":"Herhangi bir ayara atlamak için <strong>Ayarlar</strong>'da <strong>Ayarlarda ara…</strong> alanına yazın; bir işaret, açtığınızdan bu yana hangi kategorileri değiştirdiğinizi gösterir.","manual.a4640858ad4d":"Düğme ızgarasını açmak için <strong>Araçlar → Hızlı eylemler…</strong>'i seçin. <strong>Düzenle</strong>'ye, ardından <strong>Düğme ekle</strong>'ye tıklayın, her düğmenin etiketini ve rengini ayarlayın ve <strong>sayfalar</strong> ekleyin. Bir düğme bir sahneye geçebilir, bir makro çalıştırabilir, bir ses paneli pedini çalabilir ya da bir stüdyo komutu çalıştırabilir.","manual.74ff6472576d":"<strong>İpucu:</strong> Hızlı eylem düğmeleri kısayollarla aynı stüdyo komutlarını çalıştırır ve ızgara LAN dokunmatik paneliyle paylaşılır: bir kez kurun, telefonunuzda da olsun.","manual.74a883a037bc":"Ayarlar","manual.5feaf4600834":"Profiller, sahne koleksiyonları, kısayollar ve dil. Her şey bugün ücretsiz olduğundan etkinleştirilecek bir şey yoktur. <strong>Ayarlar</strong>, kategorileri olan tek bir penceredir — Genel, Görünüm, Yayın, Çıkış, Tekrar, Kısayollar, Ağ, Erişilebilirlik ve Hakkında — ve <strong>menü çubuğundan</strong> (Dosya, Düzen, Görünüm, Paneller, Profil, Sahne Koleksiyonu, Araçlar ve Yardım) açılır.","manual.9f6a04e85e39":"<strong>Uygula, uygulamak demektir.</strong> Ayarlar penceresi bir kopyayı düzenler: siz <strong>Uygula</strong> ya da <strong>Tamam</strong>'a tıklayana kadar hiçbir şey değişmez ve <strong>İptal</strong>, tema önizlemesi dahil her şeyi tam olarak eski haline getirir.","manual.3fc0968ef6f9":"<strong>Profiller ve sahne koleksiyonları:</strong> ayrı kurulumlar tutun — örneğin “Yayın” ve “Yerel kayıt” — ve <strong>Profil</strong> ile <strong>Sahne Koleksiyonu</strong> menülerinden, yeniden başlatmadan aralarında geçiş yapın.","manual.ce6f52861bdb":"<strong>Kısayollar:</strong> her eylemi çakışamayan bir listeden atayın — bir eylem için bir kısayol seçtiğinizde o kısayol diğer tüm eylemlerin listesinden kaybolur; böylece iki özellik asla aynı tuşu paylaşmaz. <strong>Yok</strong> onu yeniden serbest bırakır.","manual.be52349f05be":"<strong>Erişilebilirlik:</strong> renk körlüğüne uygun bir set dahil, mikserin ölçer renklerini seçin. Uygulamanın tamamı klavyeden kullanılabilir ve ekran okuyucular canlıya çıkışı, kaydı, yeniden bağlanmayı ve kaybolan kareleri duyurur.","manual.a79c94673558":"<strong>Dil:</strong> 18 dilden birini seçin; uygulama hemen değişir ve Arapça sağdan sola okunur.","manual.59274c49ac87":"Sorun bildirme","manual.c02ed8aec89d":"Bir sorunun geliştiriciye ulaşıp ulaşmayacağına siz karar verirsiniz ve tam olarak neyin gönderileceğini görürsünüz.","manual.4ed327c34aeb":"Uygulama kendi neden olduğu bir hatayı gösterdiğinde, yanında bir <strong>Bildir</strong> düğmesi görünür.","manual.95da4b53fdcc":"Bir çökmeden sonra, bir sonraki açılış <strong>Bildir</strong> ya da <strong>Kapat</strong> seçeneklerini sunar.","manual.6207904599f4":"<strong>Bildir</strong>, Freally Capture'ın bu sitedeki bildirim sayfasını, teknik bilgiler önceden doldurulmuş olarak tarayıcınızda açar: bunları okuyabilirsiniz ama değiştiremezsiniz. Ne yaptığınızı ve isterseniz bir e-posta adresi ekleyin. Orada <strong>Gönder</strong>'e basmadığınız sürece hiçbir şey gönderilmez.","manual.6acd4e789ccd":"Arka planda asla hiçbir şey gönderilmez ve <strong>Kapat</strong> hiçbir şey göndermez.","manual.69bd78234ffb":"Gizlilik ve ağ","manual.42f9b04c2640":"Freally Capture'da hesap ve telemetri yoktur ve bize ait bir bulut hizmeti de yoktur. İnternete tam olarak neyin çıktığı ve neyin çıkmadığı aşağıdadır.","manual.81fe73d241a8":"<strong>Hesap yok, telemetri yok.</strong> Uygulama sizden asla oturum açmanızı istemez ve sahnelerinizi, kayıtlarınızı ya da herhangi bir kullanım verisini hiçbir yere göndermez.","manual.3735a28566e9":"<strong>Yayınınız doğrudan platforma gider.</strong> Bilgisayarınızdan kurduğunuz hizmetlere iletilir — bize ait bir aktarma sunucusu yoktur.","manual.512b8fa00684":"<strong>Kayıtlarınız bilgisayarınızda kalır,</strong> seçtiğiniz klasörde. Hiçbir şey yüklenmez.","manual.c299fcfa1fde":"<strong>Yayın anahtarlarınız bilgisayarınızda kalır,</strong> maskelenmiş olarak gösterilir ve yalnızca yayın yaptığınız hizmete gönderilir.","manual.414a08bd0219":"<strong>Uzaktan konuklar eşler arası bağlanır.</strong> Herkese açık bir sinyalleşme hizmetinden yalnızca oturumun el sıkışması geçer ve bu da yalnızca siz bir oturum başlattığınızda olur.","manual.20c95c4687b3":"<strong>Bir sohbet katmanı herkese açık sohbeti okur</strong>; yönlendirdiğiniz kanaldan, oturum açmamış bir izleyicinin okuyacağı şekilde — hesap, anahtar ya da oturum açma olmadan.","manual.efe87d55bed1":"<strong>İki bileşen yalnızca ilk ihtiyaç duyduğunuzda indirilir:</strong> platformların gerektirdiği kodekler için ffmpeg ve tarayıcı kaynağı için tarayıcı çalışma ortamı. Her biri kendi yayımcısından gelir ve kullanılmadan önce doğrulanır.","manual.3601a272b3b0":"<strong>Bir güncelleme denetimi</strong>, her açılışta bir kez ve siz <strong>Güncellemeleri denetle…</strong> seçeneğini seçtiğinizde küçük bir dosya indirir. Bununla birlikte sizin ya da bilgisayarınız hakkında hiçbir şey gönderilmez ve siz evet demedikçe hiçbir şey kurulmaz.","manual.11abc96d8e21":"<strong>Bir sorun bildirimi yalnızca siz Gönder'e bastığınızda gönderilir</strong>; bildirim sayfasında, içeriğini okuduktan sonra (bkz. <a href=\"#report\">Sorun bildirme</a>).","manual.804fa6536d40":"<strong>Yapay zekâ yok.</strong> Her filtre — gürültü bastırma, kroma anahtarı, ton eşleme — klasik sinyal işlemedir. Uygulama hiçbir makine öğrenimi modeli içermez ve hiçbirini indirmez."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
